script:
var _shadowSymbols = null;
var _copiedSymbols = {};
function icon(symbolId, size) {
    size = size || "sm";
    var shadowId = "s-" + symbolId;

    if (!_shadowSymbols) {
        _shadowSymbols = document.createElement("svg");
        _shadowSymbols.id = "shadow-icons";
        _shadowSymbols.setAttribute("aria-hidden", "true");
        root_element.appendChild(_shadowSymbols);
    }

    if (!_copiedSymbols[shadowId]) {
        var src = document.getElementById(symbolId);
        if (src) {
            var clone = src.cloneNode(true);
            clone.id = shadowId;
            _shadowSymbols.appendChild(clone);
            _copiedSymbols[shadowId] = true;
        }
    }

    var isEspresso = symbolId.startsWith("es-");
    var cssClass = isEspresso ? "es-icon" : "icon";
    if (isEspresso && symbolId.includes("-solid-")) cssClass += " es-solid";
    else if (isEspresso) cssClass += " es-line";

    return "<svg class=\"" + cssClass + "\" style=\"width:14px;height:14px;stroke:currentColor;fill:currentColor;overflow:visible;display:block;\" aria-hidden=\"true\"><use href=\"#" + shadowId + "\"></use></svg>";
}
// === Ende Icon Helper ===

var methodLastschrift = "hibiscus_connect.hibiscus_connect.doctype.hibiscus_connect_sepa_lastschrift_funktionen.hibiscus_connect_sepa_lastschrift_funktionen.get_dashboard_data";
var methodUeberweisung = "hibiscus_connect.hibiscus_connect.doctype.hibiscus_connect_sepa_lastschrift_funktionen.hibiscus_connect_sepa_lastschrift_funktionen.get_ueberweisung_dashboard_data";
var methodRefreshLastschrift = "hibiscus_connect.hibiscus_connect.doctype.hibiscus_connect_sepa_lastschrift_funktionen.hibiscus_connect_sepa_lastschrift_funktionen.refresh_lastschrift_cache";
var methodRefreshUeberweisung = "hibiscus_connect.hibiscus_connect.doctype.hibiscus_connect_sepa_lastschrift_funktionen.hibiscus_connect_sepa_lastschrift_funktionen.refresh_ueberweisung_cache";
var methodBankingDashboard = "hibiscus_connect.tools.get_banking_dashboard_data";

var $loading = root_element.querySelector(".dashboard-loading");
var $content = root_element.querySelector(".dashboard-content");

var reloadIcon = icon("es-line-reload");
var infoIcon = icon("icon-solid-info");
var btnStyle = "padding: 8px 18px; display: inline-flex; align-items: center; justify-content: center; overflow: visible;";

// Speichere Daten für Modal
var ueberweisungDetails = [];

function showUeberweisungModal() {
    if (!ueberweisungDetails || ueberweisungDetails.length === 0) {
        frappe.msgprint("Keine Überweisungen vorhanden.");
        return;
    }

    var rows = ueberweisungDetails.map(function(u) {
        return "<tr>" +
            "<td>" + (u.name || "-") + "</td>" +
            "<td style=\"text-align:right;\">" + (u.betrag_formatted || "-") + "</td>" +
            "<td>" + (u.termin || "-") + "</td>" +
        "</tr>";
    }).join("");

    var html = "<table class=\"table table-bordered table-sm\">" +
        "<thead><tr><th>Empfänger</th><th style=\"text-align:right;\">Betrag</th><th>Zieltermin</th></tr></thead>" +
        "<tbody>" + rows + "</tbody>" +
    "</table>";

    frappe.msgprint({
        title: "Alle offenen Überweisungen",
        message: html,
        wide: true
    });
}

function loadDashboard() {
    $loading.style.display = "block";
    $content.style.display = "none";

    Promise.all([
        frappe.call({ method: methodLastschrift }),
        frappe.call({ method: methodUeberweisung }),
        frappe.call({ method: methodBankingDashboard })
    ]).then(function(results) {
        var lastschriftData = results[0].message;
        var ueberweisungData = results[1].message;
        var bankingData = results[2].message;

        // Speichere Details für Modal
        ueberweisungDetails = ueberweisungData ? ueberweisungData.offene || [] : [];

        var htmlLastschrift = "";
        var htmlUeberweisung = "";

        // SEPA Lastschriften
        if (lastschriftData) {
            var data = lastschriftData;
            var hasOverdue = data.count_faellig > 0;
            var bgColor = hasOverdue ? "var(--red-100)" : "var(--green-100)";
            var textColor = hasOverdue ? "var(--red-600)" : "var(--green-600)";
            var badgeIcon = hasOverdue ? icon("es-line-alert-triangle") : icon("icon-tick");

            htmlLastschrift = "<div style=\"flex: 1; display: flex; align-items: center; gap: 12px; padding: 10px 12px; background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 8px; min-width: 280px;\">" +
                "<span style=\"background-color: " + bgColor + "; color: " + textColor + "; padding: 6px 12px; display: inline-flex; align-items: center; gap: 6px; border-radius: 6px; font-weight: 600; font-size: 13px;\">" +
                    badgeIcon +
                    "<span>Einzüge</span>" +
                "</span>" +
                "<div style=\"border-left: 1px solid var(--border-color); padding-left: 10px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">Fällig:</span>" +
                    "<span style=\"font-weight: 600; margin-left: 3px;" + (hasOverdue ? " color: var(--red-500);" : "") + "\">" + data.count_faellig + "</span>" +
                    "<span class=\"text-muted\" style=\"margin-left: 2px; font-size: 11px;\">(" + data.total_faellig_formatted + ")</span>" +
                "</div>" +
                "<div style=\"border-left: 1px solid var(--border-color); padding-left: 10px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">Offen:</span>" +
                    "<span style=\"font-weight: 600; margin-left: 3px;\">" + data.count_offen + "</span>" +
                    "<span class=\"text-muted\" style=\"margin-left: 2px; font-size: 11px;\">(" + data.total_offen + ")</span>" +
                "</div>" +
                "<div style=\"margin-left: auto; display: flex; align-items: center; gap: 8px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">" + (data.last_check ? frappe.datetime.str_to_user(data.last_check) + " " + data.last_check.substring(11, 16) : "-") + "</span>" +
                    "<button class=\"btn btn-sm btn-default reload-lastschrift\" style=\"" + btnStyle + "\" title=\"Einzüge aus Hibiscus aktualisieren\">" + reloadIcon + "</button>" +
                    "<button class=\"btn btn-sm btn-default goto-lastschrift\" style=\"" + btnStyle + "\">" + icon("icon-arrow-right") + "</button>" +
                "</div>" +
            "</div>";
        }

        // Überweisungen
        if (ueberweisungData) {
            var data = ueberweisungData;
            var hasOverdue = data.count_faellig > 0;
            var bgColor = hasOverdue ? "var(--orange-100)" : "var(--green-100)";
            var textColor = hasOverdue ? "var(--orange-600)" : "var(--green-600)";
            var badgeIcon = hasOverdue ? icon("es-line-alert-triangle") : icon("icon-tick");

            htmlUeberweisung = "<div style=\"flex: 1; display: flex; align-items: center; gap: 12px; padding: 10px 12px; background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 8px; min-width: 280px;\">" +
                "<span style=\"background-color: " + bgColor + "; color: " + textColor + "; padding: 6px 12px; display: inline-flex; align-items: center; gap: 6px; border-radius: 6px; font-weight: 600; font-size: 13px;\">" +
                    badgeIcon +
                    "<span>Überweisungen</span>" +
                "</span>" +
                "<div style=\"border-left: 1px solid var(--border-color); padding-left: 10px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">Fällig:</span>" +
                    "<span style=\"font-weight: 600; margin-left: 3px;" + (hasOverdue ? " color: var(--orange-500);" : "") + "\">" + data.count_faellig + "</span>" +
                    "<span class=\"text-muted\" style=\"margin-left: 2px; font-size: 11px;\">(" + data.total_faellig_formatted + ")</span>" +
                "</div>" +
                "<div style=\"border-left: 1px solid var(--border-color); padding-left: 10px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">Offen:</span>" +
                    "<span style=\"font-weight: 600; margin-left: 3px;\">" + data.count_offen + "</span>" +
                    "<span class=\"text-muted\" style=\"margin-left: 2px; font-size: 11px;\">(" + data.total_offen + ")</span>" +
                "</div>" +
                "<div style=\"margin-left: auto; display: flex; align-items: center; gap: 8px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">" + (data.last_check ? frappe.datetime.str_to_user(data.last_check) + " " + data.last_check.substring(11, 16) : "-") + "</span>" +
                    "<button class=\"btn btn-sm btn-default info-ueberweisung\" style=\"" + btnStyle + "\" title=\"Offene Überweisungen anzeigen\">" + infoIcon + "</button>" +
                    "<button class=\"btn btn-sm btn-default reload-ueberweisung\" style=\"" + btnStyle + "\" title=\"Überweisungen aus Hibiscus aktualisieren\">" + reloadIcon + "</button>" +
                "</div>" +
            "</div>";
        }

        // Rücklastschriften
        var htmlChargeback = "";
        var htmlUnbooked = "";

        if (bankingData) {
            var cbCount = bankingData.chargeback_count;
            var hasChargebacks = cbCount > 0;
            var cbBgColor = hasChargebacks ? "var(--red-100)" : "var(--green-100)";
            var cbTextColor = hasChargebacks ? "var(--red-600)" : "var(--green-600)";
            var cbIcon = hasChargebacks ? icon("es-line-alert-triangle") : icon("icon-tick");

            htmlChargeback = "<div style=\"flex: 1; display: flex; align-items: center; gap: 12px; padding: 10px 12px; background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 8px; min-width: 280px;\">" +
                "<span style=\"background-color: " + cbBgColor + "; color: " + cbTextColor + "; padding: 6px 12px; display: inline-flex; align-items: center; gap: 6px; border-radius: 6px; font-weight: 600; font-size: 13px;\">" +
                    cbIcon +
                    "<span>Rücklastschriften</span>" +
                "</span>" +
                "<div style=\"border-left: 1px solid var(--border-color); padding-left: 10px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">Offen:</span>" +
                    "<span style=\"font-weight: 600; margin-left: 3px;" + (hasChargebacks ? " color: var(--red-500);" : "") + "\">" + cbCount + "</span>" +
                    "<span class=\"text-muted\" style=\"margin-left: 2px; font-size: 11px;\">(" + bankingData.chargeback_total + ")</span>" +
                "</div>" +
                "<div style=\"margin-left: auto; display: flex; align-items: center; gap: 8px;\">" +
                    "<button class=\"btn btn-sm btn-default goto-chargebacks\" style=\"" + btnStyle + "\" title=\"Rücklastschriften anzeigen\">" + icon("icon-arrow-right") + "</button>" +
                "</div>" +
            "</div>";

            // Unverbuchte Zahlungen
            var ubCount = bankingData.unbooked_count;
            var hasUnbooked = ubCount > 0;
            var ubBgColor = hasUnbooked ? "var(--yellow-100)" : "var(--green-100)";
            var ubTextColor = hasUnbooked ? "var(--yellow-600)" : "var(--green-600)";
            var ubIcon = hasUnbooked ? icon("es-line-alert-triangle") : icon("icon-tick");

            htmlUnbooked = "<div style=\"flex: 1; display: flex; align-items: center; gap: 12px; padding: 10px 12px; background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 8px; min-width: 280px;\">" +
                "<span style=\"background-color: " + ubBgColor + "; color: " + ubTextColor + "; padding: 6px 12px; display: inline-flex; align-items: center; gap: 6px; border-radius: 6px; font-weight: 600; font-size: 13px;\">" +
                    ubIcon +
                    "<span>Unverbucht</span>" +
                "</span>" +
                "<div style=\"border-left: 1px solid var(--border-color); padding-left: 10px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">Eingänge:</span>" +
                    "<span style=\"font-weight: 600; margin-left: 3px;\">" + bankingData.unbooked_count_positive + "</span>" +
                    "<span class=\"text-muted\" style=\"margin-left: 2px; font-size: 11px;\">(" + bankingData.unbooked_total_positive + ")</span>" +
                "</div>" +
                "<div style=\"border-left: 1px solid var(--border-color); padding-left: 10px;\">" +
                    "<span class=\"text-muted\" style=\"font-size: 10px;\">Ausgänge:</span>" +
                    "<span style=\"font-weight: 600; margin-left: 3px;\">" + bankingData.unbooked_count_negative + "</span>" +
                    "<span class=\"text-muted\" style=\"margin-left: 2px; font-size: 11px;\">(" + bankingData.unbooked_total_negative + ")</span>" +
                "</div>" +
                "<div style=\"margin-left: auto; display: flex; align-items: center; gap: 8px;\">" +
                    "<button class=\"btn btn-sm btn-default goto-unbooked\" style=\"" + btnStyle + "\" title=\"Unverbuchte Zahlungen anzeigen\">" + icon("icon-arrow-right") + "</button>" +
                "</div>" +
            "</div>";
        }

        var allHtml = "";
        if (htmlLastschrift || htmlUeberweisung) {
            allHtml += "<div style=\"display: flex; gap: 10px; flex-wrap: wrap;\">" + htmlLastschrift + htmlUeberweisung + "</div>";
        }
        if (htmlChargeback || htmlUnbooked) {
            allHtml += "<div style=\"display: flex; gap: 10px; flex-wrap: wrap; margin-top: 10px;\">" + htmlChargeback + htmlUnbooked + "</div>";
        }

        if (allHtml) {
            $content.innerHTML = allHtml;
            $loading.style.display = "none";
            $content.style.display = "block";

            // === Event Handlers ===

            // Reload Lastschriften
            var btnLastschrift = $content.querySelector(".reload-lastschrift");
            if (btnLastschrift) {
                btnLastschrift.addEventListener("click", function() {
                    var btn = this;
                    var originalIcon = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = "<span class=\"spinner-border spinner-border-sm\"></span>";

                    frappe.call({ method: methodRefreshLastschrift }).then(function() {
                        frappe.show_alert({message: "Einzüge aktualisiert", indicator: "green"}, 3);
                        loadDashboard();
                    }).catch(function(err) {
                        frappe.show_alert({message: "Fehler beim Aktualisieren", indicator: "red"}, 3);
                        btn.disabled = false;
                        btn.innerHTML = originalIcon;
                    });
                });
            }

            // Goto Lastschriften
            var btnGoto = $content.querySelector(".goto-lastschrift");
            if (btnGoto) {
                btnGoto.addEventListener("click", function() {
                    frappe.set_route("hibiscus-connect-sepa-lastschrift-funktionen");
                });
            }

            // Info Überweisungen
            var btnInfo = $content.querySelector(".info-ueberweisung");
            if (btnInfo) {
                btnInfo.addEventListener("click", showUeberweisungModal);
            }

            // Reload Überweisungen
            var btnUeberweisung = $content.querySelector(".reload-ueberweisung");
            if (btnUeberweisung) {
                btnUeberweisung.addEventListener("click", function() {
                    var btn = this;
                    var originalIcon = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = "<span class=\"spinner-border spinner-border-sm\"></span>";

                    frappe.call({ method: methodRefreshUeberweisung }).then(function() {
                        frappe.show_alert({message: "Überweisungen aktualisiert", indicator: "green"}, 3);
                        loadDashboard();
                    }).catch(function(err) {
                        frappe.show_alert({message: "Fehler beim Aktualisieren", indicator: "red"}, 3);
                        btn.disabled = false;
                        btn.innerHTML = originalIcon;
                    });
                });
            }

            // Goto Chargebacks
            var btnChargebacks = $content.querySelector(".goto-chargebacks");
            if (btnChargebacks) {
                btnChargebacks.addEventListener("click", function() {
                    frappe.set_route("List", "Hibiscus Connect Transaction", { "status": "chargeback" });
                });
            }

            // Goto Unbooked
            var btnUnbooked = $content.querySelector(".goto-unbooked");
            if (btnUnbooked) {
                btnUnbooked.addEventListener("click", function() {
                    frappe.set_route("List", "Hibiscus Connect Transaction", { "status": "new" });
                });
            }

        } else {
            $loading.innerHTML = "<span class=\"text-muted\">Keine Daten</span>";
        }
    }).catch(function(err) {
        $loading.innerHTML = "<span class=\"text-danger\">Fehler beim Laden</span>";
        console.error(err);
    });
}

loadDashboard();

style:
#shadow-icons {
    position: absolute;
    width: 0;
    height: 0;
    overflow: hidden;
}
